import {
  IsEmail,
  IsNotEmpty,
  IsOptional,
  IsString,
  IsNumber,
} from 'class-validator';
import { Type } from 'class-transformer';
import { MaxDecimalPlaces } from '../../utils/validation/max-decimal-places';
import { IsOptionalNotNull } from '../../utils/validation/optional';

export class CreateSupplierDto {
  // Generated by the server; any client value is ignored.
  @IsOptional()
  @IsString()
  code?: string;

  @IsString()
  @IsNotEmpty()
  name: string;

  @IsOptional()
  @IsString()
  taxNumber?: string;

  @IsOptional()
  @IsString()
  contactPerson?: string;

  @IsOptional()
  @IsString()
  phone?: string;

  @IsOptional()
  @IsEmail()
  email?: string;

  // Can be negative: + = we owe the supplier, - = the supplier owes us
  // (advance payment / unrefunded return). Max 2 decimals.
  @IsOptionalNotNull()
  @Type(() => Number)
  @IsNumber()
  @MaxDecimalPlaces(2)
  openingBalance?: number;
}
